<?php elseif($page==='forbidden'): ?><main class="container dashboard"><div class="empty-state"><h1>Access restricted</h1><p>This page is only available to student accounts.</p><a class="primary-btn" href="index.php?page=dashboard">Return to dashboard</a></div></main>
